// Shared vocabulary of the hostile upload corpus (spec Appendix A, H-01 to H-44).
//
// One fixture is one Appendix A row. A fixture is generated by code from templates and never
// stored as a file, so no malicious file is committed (which also avoids antivirus noise) and the
// payload markers can be searched for in whatever the application stored or served.
//
// This module and the generators import nothing from the test runner: `e2e/tests/branding.spec.ts`
// and `write-hostile.ts` use them outside Vitest.
import type { ProblemCode } from '@m365portal/shared/problem';

/** `H-01` to `H-44`. */
export type HostileId = `H-${string}`;

/** The upload slots of `POST /api/v1/branding/assets?slot=`. */
export type SlotName = 'logoLight' | 'logoDark' | 'compact';

/** Warning codes of a successful upload (contract section 6). */
export type UploadWarningCode = 'svg_content_removed' | 'animation_flattened';

/** Categories of the `svg_content_removed` warning (contract section 6). */
export type RemovalCategory =
  | 'script'
  | 'event_handler'
  | 'external_reference'
  | 'foreign_object'
  | 'style'
  | 'animation'
  | 'filter'
  | 'unknown_element'
  | 'unknown_attribute'
  | 'processing_instruction'
  | 'unresolved_reference';

/**
 * A pixel of the stored result that must have a given colour. `x` and `y` are fractions of the
 * output width and height (0 to 1), so the probe does not depend on the size the pipeline picks.
 */
export interface ColourProbe {
  readonly x: number;
  readonly y: number;
  readonly rgb: readonly [number, number, number];
  /** Largest allowed difference per channel. */
  readonly tolerance: number;
}

/** Accepted: the image is stored as a PNG. "Neutralised" is accepted with `svg_content_removed`. */
export interface AcceptedOutcome {
  readonly kind: 'accepted';
  /** Exactly these warning codes are reported (in any order), plus any of `optionalWarnings`. */
  readonly warnings: readonly UploadWarningCode[];
  /**
   * Warnings the spec leaves open: reported or not, both are fine (H-19: an out-of-range declared
   * size may or may not be reported as removed). They are not part of what the row asserts.
   */
  readonly optionalWarnings?: readonly UploadWarningCode[];
  /** `svg_content_removed` reports at least these categories. */
  readonly categories?: readonly RemovalCategory[];
  /** The stored PNG has this size (after orientation and fitting). */
  readonly size?: { readonly width: number; readonly height: number };
  /** The stored PNG has these colours. */
  readonly probes?: readonly ColourProbe[];
}

/** Rejected with a stable problem code; the HTTP status is the one of the registry. */
export interface RejectedOutcome {
  readonly kind: 'rejected';
  readonly code: ProblemCode;
}

/** An answer that has a status but no registry code (a Node-level 408, a 404 for a hostile path). */
export interface StatusOutcome {
  readonly kind: 'status';
  readonly status: number;
  /** The connection is closed by the server afterwards. */
  readonly closed?: boolean;
}

/** Any one of these is acceptable (H-19, H-24: the spec allows more than one safe outcome). */
export interface OneOfOutcome {
  readonly kind: 'oneOf';
  readonly outcomes: readonly ExpectedOutcome[];
}

/** The body was cut off while it streamed: no answer is required, nothing may remain (H-36). */
export interface CutOffOutcome {
  readonly kind: 'cutOff';
}

/** Many simultaneous valid uploads: at most `maxRunning` at once, `maxQueued` wait, the rest 429. */
export interface BurstOutcome {
  readonly kind: 'burst';
  readonly total: number;
  readonly maxRunning: number;
  readonly maxQueued: number;
  /** `maxRunning + maxQueued` requests fit; each of them ends accepted. */
  readonly minAccepted: number;
  readonly refusedCode: ProblemCode;
}

/** The organisation name is stored as plain text, byte for byte (H-44). */
export interface StoredAsTextOutcome {
  readonly kind: 'storedAsText';
}

export type ExpectedOutcome =
  | AcceptedOutcome
  | RejectedOutcome
  | StatusOutcome
  | OneOfOutcome
  | CutOffOutcome
  | BurstOutcome
  | StoredAsTextOutcome;

/** What the generators may need from the environment of one run. */
export interface HostileContext {
  /**
   * Origin of a listener the test owns (`http://127.0.0.1:<port>`, no trailing slash). Every
   * external reference of a payload points here, so a connection can be seen and counted.
   */
  readonly listenerOrigin: string;
  /** A directory the fixture may write marker files to (H-14, H-16). Absolute path. */
  readonly workDir: string;
}

/** The context used when a test does not care: nothing listens there and nothing is written. */
export const DEFAULT_CONTEXT: HostileContext = Object.freeze({
  listenerOrigin: 'http://127.0.0.1:9',
  workDir: '/nonexistent/m365portal-hostile',
});

/** How a body is sent over a socket (H-36, H-37). */
export interface TransportPlan {
  /** `chunked` sends no `Content-Length`. */
  readonly framing: 'chunked' | 'content-length';
  readonly chunkBytes: number;
  /** The client destroys the connection after this many body bytes. */
  readonly abortAfterBytes?: number;
  /** Real time between two chunks; the slow upload of H-37. */
  readonly delayMsPerChunk?: number;
  /** The test server runs with this shortened `requestTimeout`. */
  readonly serverRequestTimeoutMs?: number;
  /**
   * Node checks the request timeout only every `connectionsCheckingInterval` (30 s by default), so a
   * test server with a shortened `requestTimeout` must shorten this as well, or the 408 comes late.
   */
  readonly serverCheckIntervalMs?: number;
}

interface InputBase {
  /** Short name of the variant, unique inside a fixture. */
  readonly label: string;
  readonly expected: ExpectedOutcome;
}

/** A file for `POST /api/v1/branding/assets`. */
export interface UploadInput extends InputBase {
  readonly kind: 'upload';
  bytes(context?: HostileContext): Promise<Uint8Array>;
  /** The file name the client claims. Never read by the server (H-31, H-32, H-38). */
  readonly filename?: string;
  /** The media type the client claims for the part. Never read by the server. */
  readonly contentType?: string;
  readonly slot?: SlotName;
  readonly transport?: TransportPlan;
  /**
   * Which layer decides the outcome. `image` (the default) is the image pipeline: it can be run
   * without HTTP. `http` is the transport: size caps of the request, timeouts, aborted bodies, names
   * in the multipart envelope. Only the HTTP adapter can run those.
   */
  readonly layer?: 'image' | 'http';
}

/** A body for `POST /api/v1/branding/import` (H-42). */
export interface ImportInput extends InputBase {
  readonly kind: 'import';
  bytes(context?: HostileContext): Promise<Uint8Array>;
}

/** A request for `GET <target>` (H-43). `target` is sent exactly as written, no re-encoding. */
export interface AssetGetInput extends InputBase {
  readonly kind: 'assetGet';
  readonly target: string;
}

/** An organisation name for `PUT /api/v1/branding` (H-44). */
export interface OrgNameInput extends InputBase {
  readonly kind: 'orgName';
  readonly name: string;
  /** Text that must not appear verbatim in served HTML or the manifest. */
  readonly inertCanaries: readonly string[];
}

/** Many valid images sent at once (H-39). */
export interface BurstInput extends InputBase {
  readonly kind: 'burst';
  images(context?: HostileContext): Promise<readonly Uint8Array[]>;
}

export type HostileInput = UploadInput | ImportInput | AssetGetInput | OrgNameInput | BurstInput;

/** One Appendix A row, as code. */
export interface HostileFixture {
  readonly id: HostileId;
  /** The Category column of the row, verbatim. */
  readonly category: string;
  /** What the payload is, in one line. */
  readonly summary: string;
  /**
   * Strings that appear in the generated bytes of some input (in any of the encodings
   * `markerPresentIn` knows) and that must appear in no stored or served byte afterwards.
   */
  readonly markers: readonly string[];
  /**
   * Strings that do not appear in the input but sit on disk or in the system (the content of a
   * marker file that an XXE payload tries to read). They must not appear in any stored or served
   * byte either.
   */
  readonly fileMarkers: readonly string[];
  readonly inputs: readonly HostileInput[];
  /** Writes the files the payload points at (H-14, H-16). Idempotent. */
  prepare(context: HostileContext): Promise<void>;
  /** The first input as bytes: the primary payload of the row. */
  bytes(context?: HostileContext): Promise<Uint8Array>;
  /** The outcomes of all inputs, in order: the Expected column of the row. */
  readonly expected: readonly ExpectedOutcome[];
}

export interface FixtureDefinition {
  readonly id: HostileId;
  readonly category: string;
  readonly summary: string;
  readonly markers?: readonly string[];
  readonly fileMarkers?: readonly string[];
  readonly inputs: readonly HostileInput[];
  readonly prepare?: (context: HostileContext) => Promise<void>;
}

/** The text of an input as bytes: its body, its target or its name. */
async function primaryBytes(input: HostileInput, context: HostileContext): Promise<Uint8Array> {
  switch (input.kind) {
    case 'upload':
    case 'import':
      return input.bytes(context);
    case 'assetGet':
      return utf8(input.target);
    case 'orgName':
      return utf8(input.name);
    case 'burst': {
      const [first] = await input.images(context);
      if (first === undefined) throw new Error('a burst input has no image');
      return first;
    }
  }
}

export function defineFixture(definition: FixtureDefinition): HostileFixture {
  const first = definition.inputs[0];
  if (first === undefined) throw new Error(`${definition.id} has no input`);
  const labels = new Set(definition.inputs.map((input) => input.label));
  if (labels.size !== definition.inputs.length) {
    throw new Error(`${definition.id} has two inputs with the same label`);
  }
  return {
    id: definition.id,
    category: definition.category,
    summary: definition.summary,
    markers: definition.markers ?? [],
    fileMarkers: definition.fileMarkers ?? [],
    inputs: definition.inputs,
    prepare: definition.prepare ?? (() => Promise.resolve()),
    bytes: (context = DEFAULT_CONTEXT) => primaryBytes(first, context),
    expected: definition.inputs.map((input) => input.expected),
  };
}

// Outcome builders, so a generator reads like the Expected column.

/** Accepted without any warning. */
export function accepted(
  extra: Partial<Omit<AcceptedOutcome, 'kind' | 'warnings'>> = {},
): AcceptedOutcome {
  return { kind: 'accepted', warnings: [], ...extra };
}

/** Neutralised: accepted, rasterised, the dangerous content gone and `svg_content_removed` reported. */
export function neutralised(categories?: readonly RemovalCategory[]): AcceptedOutcome {
  return categories === undefined
    ? { kind: 'accepted', warnings: ['svg_content_removed'] }
    : { kind: 'accepted', warnings: ['svg_content_removed'], categories };
}

export function rejected(code: ProblemCode): RejectedOutcome {
  return { kind: 'rejected', code };
}

export function oneOf(...outcomes: readonly ExpectedOutcome[]): OneOfOutcome {
  return { kind: 'oneOf', outcomes };
}

// Byte helpers.

const ENCODER = new TextEncoder();

export function utf8(text: string): Uint8Array {
  return ENCODER.encode(text);
}

export function concatBytes(...parts: readonly Uint8Array[]): Uint8Array {
  let length = 0;
  for (const part of parts) length += part.length;
  const out = new Uint8Array(length);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/** `Uint8Array` of exactly the bytes of a Buffer or typed array view, detached from its pool. */
export function toBytes(view: ArrayBufferView): Uint8Array {
  return new Uint8Array(view.buffer.slice(view.byteOffset, view.byteOffset + view.byteLength));
}

/** A deterministic 32-bit generator (xorshift32): the same seed gives the same bytes everywhere. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0 || 0x9e3779b9;
  return () => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;
    return state;
  };
}

/** One kind of text the workers must be able to find in a payload and must not find in a result. */
export function markerOf(id: HostileId, part: string): string {
  return `M365HOSTILE-${id.slice(2)}-${part}`;
}
